package com.example.ParkingLot.entity;

import java.util.List;

public class ParkingFloor {
    int floorNumber;
    List<ParkingSpot> parkingSpotList;


    ParkingSpot getAvailableSpot(Vehicle vehicle){
         for(int i =0;i<parkingSpotList.size();i++)
         {
             if(!parkingSpotList.get(i).isOccupied &&  parkingSpotList.get(i).vehicleType.equals((vehicle.type))) return parkingSpotList.get(i);
         }
         return null;
    }


}

package com.example.ParkingLot.entity;

import java.util.List;

public class ParkingFloor {
    int floorNumber;
    List<ParkingSpot> parkingSpotList;


    ParkingSpot getAvailableSpot(Vehicle vehicle){
         // defensive checks
         if (vehicle == null || parkingSpotList == null) return null;

         for (int i = 0; i < parkingSpotList.size(); i++) {
             ParkingSpot spot = parkingSpotList.get(i);
             // Compare enum values using == (safe) and avoid calling equals on a possibly null field.
             if (!spot.isOccupied && spot.vehicleType == vehicle.getType()) {
                 return spot;
             }
         }
         return null;
    }


}

