package com.example.ParkingLot.entity;

import com.example.ParkingLot.enums.VehicleType;

public abstract class Vehicle {
    String vehicleNumber;
    VehicleType type;



    int calculateFee(int hours){
        return 0;
    }

    // Public getter for the vehicle type. Use this instead of accessing the field directly
    // from other classes. Keeps the API stable if the field visibility changes.
    public VehicleType getType() {
        return this.type;
    }
}
